// Signs Android release builds with the upload key from CI env vars, and sets versionCode
// from ANDROID_VERSION_CODE. `android/` is generated by `expo prebuild`, so this is the only
// place the signing setup lives. Without the env vars, release builds fall back to debug signing.
const { withAppBuildGradle } = require('expo/config-plugins');

const RELEASE_SIGNING = `
        release {
            if (System.getenv('ANDROID_KEYSTORE_PATH')) {
                storeFile file(System.getenv('ANDROID_KEYSTORE_PATH'))
                storeType 'pkcs12'
                storePassword System.getenv('ANDROID_KEYSTORE_PASSWORD')
                keyAlias System.getenv('ANDROID_KEY_ALIAS')
                keyPassword System.getenv('ANDROID_KEYSTORE_PASSWORD')
            }
        }`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let gradle = cfg.modResults.contents;
    if (gradle.includes('ANDROID_KEYSTORE_PATH')) return cfg;

    const replace = (pattern, replacement, what) => {
      if (!pattern.test(gradle)) throw new Error(`withReleaseSigning: couldn't find ${what}`);
      gradle = gradle.replace(pattern, replacement);
    };
    replace(/(signingConfigs\s*\{)/, `$1${RELEASE_SIGNING}`, 'signingConfigs');
    replace(
      /(release\s*\{[^}]*?)signingConfig signingConfigs\.debug/,
      `$1signingConfig System.getenv('ANDROID_KEYSTORE_PATH') ? signingConfigs.release : signingConfigs.debug`,
      'release signingConfig',
    );
    replace(
      /versionCode \d+/,
      `versionCode((System.getenv('ANDROID_VERSION_CODE') ?: '1').toInteger())`,
      'versionCode',
    );
    cfg.modResults.contents = gradle;
    return cfg;
  });
};
